"""``trading_os.shared.numbers`` against what JavaScript itself prints (``tests/golden/numbers.json``, generated by Node): the
ported detectors format and round numbers the way the originals did, ties included."""

from __future__ import annotations

import json
import math
from pathlib import Path
from typing import Any

import pytest

from trading_os.shared.numbers import js_round, number_to_string, to_fixed

ROWS: list[dict[str, Any]] = json.loads(
    (Path(__file__).parents[1] / "golden" / "numbers.json").read_text(encoding="utf-8"),
    parse_int=float,  # every JSON number is a double here: 123456789012345680000 must not become an exact Python int
)["rows"]


def value_of(row: dict[str, Any]) -> float:
    return -0.0 if row["value"] == "-0" else float(row["value"])


def test_the_vectors_cover_ties_signs_and_extremes() -> None:
    values = [value_of(r) for r in ROWS]
    assert len(values) > 600
    assert any(v == 2.5 for v in values) and any(v == -2.5 for v in values) and any(v == 0.125 for v in values)
    assert any(abs(v) < 1e-6 for v in values) and any(abs(v) >= 1e21 for v in values)


def test_math_round_rounds_ties_toward_positive_infinity() -> None:
    for row in ROWS:
        value = value_of(row)
        assert js_round(value) == row["round"], value
    assert js_round(2.5) == 3 and js_round(-2.5) == -2 and js_round(0.5) == 1  # (Python's round() says 2, -2, 0)


def test_to_fixed_rounds_the_exact_binary_value_half_up() -> None:
    for row in ROWS:
        value = value_of(row)
        for digits, expected in row["toFixed"].items():
            if expected is not None:
                assert to_fixed(value, int(digits)) == expected, (value, digits)
    assert to_fixed(0.5, 0) == "1" and to_fixed(2.5, 0) == "3" and to_fixed(1.005, 2) == "1.00"  # (format() says 0, 2)


def test_a_number_prints_like_javascript() -> None:
    for row in ROWS:
        value = value_of(row)
        assert number_to_string(value) == row["string"], value
    assert number_to_string(3.0) == "3" and number_to_string(0.25) == "0.25" and number_to_string(1e21) == "1e+21"


def test_non_finite_numbers_print_like_javascript() -> None:
    assert number_to_string(math.inf) == "Infinity" and number_to_string(-math.inf) == "-Infinity"
    assert number_to_string(math.nan) == "NaN" and to_fixed(math.nan, 2) == "NaN"
    assert js_round(math.inf) == math.inf and math.isnan(js_round(math.nan))


@pytest.mark.parametrize("value", [0.0, -0.0])
def test_zero_has_no_sign_in_javascript(value: float) -> None:
    assert to_fixed(value, 2) == "0.00" and number_to_string(value) == "0"
